const res = pw.response.body;

// Ambil data dasar
const token = res.auth.token;
const userId = res.data.id;

// Simpan ke environment
pw.env.set("token", token);
pw.env.set("user_id", String(userId));

// Debug (biar gampang ngecek)
console.log("Token:", token);
console.log("User ID:", userId);

const res = pw.response.body;

// Ambil data dasar
const token = res.auth.token;
const userId = res.data.id;

// Simpan ke environment
pw.env.set("token", token);
pw.env.set("user_id", String(userId));

// Debug (biar gampang ngecek)
console.log("Token:", token);
console.log("User ID:", userId);

// Hapus token & data user
pw.env.unset("token");
pw.env.unset("user_id");

// Hapus koperasi aktif & list koperasi
pw.env.unset("koperasi_id");
pw.env.unset("koperasi_list");

// Optional: kalau nanti kamu punya data lain
